import { PageHeader } from '@gntik-ai/blocks';
import {
  ChatAnnouncer,
  ChatComposer,
  ChatLayout,
  ChatMessage,
  CitationList,
  Markdown,
  SuggestionChips,
  ToolCallCard,
  type ChatFeedback,
  type ChatRole,
  type CitationSource,
  type Suggestion,
  type ToolCallStatus,
} from '@gntik-ai/chat';
import { SquarePen } from '@gntik-ai/icons';
import { Page, TooltipProvider, type BreadcrumbItem } from '@gntik-ai/ui';
import { useEffect, useRef, useState } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import {
  assistantBreadcrumbs,
  assistantReply,
  assistantSources,
  assistantSuggestions,
  assistantTool,
  chunkReply,
  type AssistantTool,
} from './data';

interface Turn {
  id: number;
  role: ChatRole;
  text: string;
  time: Date;
  streaming?: boolean;
  tool?: { status: ToolCallStatus; durationMs?: number };
  sources?: boolean;
  feedback?: ChatFeedback;
}

export interface AssistantChatProps {
  title: string;
  suggestions: Suggestion[];
  /** Sources cited under the reply and listed in the details panel. */
  sources: CitationSource[];
  /** Mock tool call run before each reply. */
  tool: AssistantTool;
  /** Mock reply (markdown), streamed in chunks. */
  reply: string;
  /** Milliseconds between streamed chunks. */
  tickMs: number;
  /** Show the details panel. */
  withPanel: boolean;
  /** Called with each prompt the user sends. */
  onSend: (text: string) => void;
  onFeedback: (feedback: ChatFeedback) => void;
  breadcrumbs: BreadcrumbItem[];
  currentHref: string;
  /** ConsoleShell props (app nav, user, workspaces, sidebar footer, topbar…). */
  shell: Omit<ConsoleShellProps, 'children'>;
}

/** Assistant chat: ConsoleShell + Page + ChatLayout with a mock-streamed reply (timers cleared on Stop and unmount). */
export default function AssistantChatPage(props: Partial<AssistantChatProps>) {
  const {
    title = 'Assistant',
    suggestions = assistantSuggestions,
    sources = assistantSources,
    tool = assistantTool,
    reply = assistantReply,
    tickMs = 30,
    withPanel = true,
    onSend,
    onFeedback,
    breadcrumbs = assistantBreadcrumbs,
    currentHref = '/assistant',
    shell,
  } = props;
  const [turns, setTurns] = useState<Turn[]>([]);
  const [streaming, setStreaming] = useState(false);
  const nextId = useRef(1);
  const [timers] = useState(() => new Set<ReturnType<typeof setTimeout>>());

  const clearTimers = () => {
    timers.forEach((t) => clearTimeout(t));
    timers.clear();
  };
  useEffect(
    () => () => {
      timers.forEach((t) => clearTimeout(t));
      timers.clear();
    },
    [timers],
  );
  const later = (fn: () => void, ms: number) => {
    const t = setTimeout(() => {
      timers.delete(t);
      fn();
    }, ms);
    timers.add(t);
  };

  const patch = (id: number, fn: (t: Turn) => Turn) => setTurns((ts) => ts.map((t) => (t.id === id ? fn(t) : t)));

  const respond = () => {
    clearTimers();
    const toolId = nextId.current++;
    const replyId = nextId.current++;
    const now = new Date();
    setStreaming(true);
    setTurns((ts) => [
      ...ts,
      { id: toolId, role: 'tool', text: '', time: now, tool: { status: 'running' } },
      { id: replyId, role: 'assistant', text: '', time: now, streaming: true },
    ]);
    const pieces = chunkReply(reply);
    const startAt = tool.durationMs;
    later(() => patch(toolId, (t) => ({ ...t, tool: { status: 'succeeded', durationMs: tool.durationMs } })), startAt);
    pieces.forEach((piece, i) => later(() => patch(replyId, (t) => ({ ...t, text: t.text + piece })), startAt + (i + 1) * tickMs));
    later(() => {
      patch(replyId, (t) => ({ ...t, streaming: false, sources: true }));
      setStreaming(false);
    }, startAt + (pieces.length + 1) * tickMs);
  };

  const send = (text: string) => {
    setTurns((ts) => [...ts, { id: nextId.current++, role: 'user', text, time: new Date() }]);
    onSend?.(text);
    respond();
  };

  const stop = () => {
    clearTimers();
    setTurns((ts) =>
      ts.map((t) =>
        t.streaming ? { ...t, streaming: false } : t.tool?.status === 'running' ? { ...t, tool: { status: 'failed', durationMs: 0 } } : t,
      ),
    );
    setStreaming(false);
  };

  const retry = (id: number) => {
    setTurns((ts) => {
      const at = ts.findIndex((t) => t.id === id);
      // Drop the reply and the tool call that preceded it.
      const cut = at > 0 && ts[at - 1]?.role === 'tool' ? at - 1 : at;
      return ts.slice(0, cut);
    });
    respond();
  };

  const newConversation = () => {
    clearTimers();
    setTurns([]);
    setStreaming(false);
  };

  const lastReply = [...turns].reverse().find((t) => t.role === 'assistant' && !t.streaming)?.text;

  return (
    <ConsoleShell breadcrumbs={breadcrumbs} currentHref={currentHref} {...shell}>
      <Page
        width="full"
        header={
          <PageHeader
            breadcrumbs={null}
            title={title}
            description="Ask about projects, deployments, invoices and members. Answers cite their sources."
            status=""
            meta={[]}
            tabs={null}
            actions={[{ label: 'New conversation', icon: SquarePen, variant: 'secondary', disabled: turns.length === 0, onClick: newConversation }]}
          />
        }
      >
        <TooltipProvider>
          <div className="h-[680px] min-h-0 overflow-hidden rounded-xl border border-border">
            <ChatLayout
              header={<h2 className="px-4 py-3 text-[13px] font-semibold text-foreground">{turns.length === 0 ? 'New conversation' : 'Conversation'}</h2>}
              panel={
                withPanel ? (
                  <div className="flex flex-col gap-4 p-4 text-[13px]">
                    <div>
                      <h2 className="font-semibold text-foreground">Details</h2>
                      <p className="mt-1 text-muted-foreground">Read access to projects, deployments, invoices and members in this workspace.</p>
                    </div>
                    <CitationList sources={sources} heading="Context sources" />
                  </div>
                ) : undefined
              }
              composer={<ChatComposer onSubmit={send} streaming={streaming} onStop={stop} maxLength={4000} />}
            >
              {turns.length === 0 && (
                <div className="flex flex-col gap-5 pt-10">
                  <h3 className="text-center text-[20px] font-semibold tracking-tight text-foreground">How can I help?</h3>
                  <SuggestionChips suggestions={suggestions} onSelect={send} />
                </div>
              )}
              {turns.map((t) => {
                if (t.role === 'tool' && t.tool) {
                  return (
                    <ChatMessage key={t.id} role="tool" author="Tool" timestamp={t.time}>
                      <ToolCallCard
                        name={tool.name}
                        status={t.tool.status}
                        durationMs={t.tool.durationMs}
                        args={tool.args}
                        result={t.tool.status === 'succeeded' ? tool.result : undefined}
                        error={t.tool.status === 'failed' ? 'Stopped by the user.' : undefined}
                      />
                    </ChatMessage>
                  );
                }
                if (t.role === 'assistant') {
                  return (
                    <ChatMessage
                      key={t.id}
                      role="assistant"
                      timestamp={t.time}
                      streaming={t.streaming}
                      copyText={t.text}
                      onRetry={streaming ? undefined : () => retry(t.id)}
                      feedback={t.feedback ?? null}
                      onFeedback={(f) => {
                        patch(t.id, (x) => ({ ...x, feedback: f }));
                        onFeedback?.(f);
                      }}
                    >
                      {t.text && <Markdown streaming={t.streaming}>{t.text}</Markdown>}
                      {t.sources && <CitationList sources={sources} className="mt-3" />}
                    </ChatMessage>
                  );
                }
                return (
                  <ChatMessage key={t.id} role={t.role} timestamp={t.time}>
                    {t.text}
                  </ChatMessage>
                );
              })}
              <ChatAnnouncer streaming={streaming} lastReply={lastReply} />
            </ChatLayout>
          </div>
        </TooltipProvider>
      </Page>
    </ConsoleShell>
  );
}

import type { CitationSource, Suggestion } from '@gntik-ai/chat';
import type { BreadcrumbItem } from '@gntik-ai/ui';

/** Mock tool call the assistant runs before answering. */
export interface AssistantTool {
  name: string;
  args: unknown;
  result: unknown;
  durationMs: number;
}

export const assistantSuggestions: Suggestion[] = [
  { label: 'Summarise this week’s deployments', description: 'What shipped across projects and what rolled back' },
  { label: 'Which invoices are still open?', description: 'Unpaid invoices from last month' },
  { label: 'Who has admin access?', description: 'Members with an admin role' },
  { label: 'Why did the last build fail?', description: 'Likely cause and a fix' },
];

export const assistantSources: CitationSource[] = [
  { title: 'Deployment history · web-app', url: 'https://app.example.com/projects/web-app/deployments', snippet: '14 deployments in the last 7 days, 1 rolled back.' },
  { title: 'Rollback guide', url: 'https://docs.example.com/deployments/rollback', snippet: 'Roll back from the Deployments page or with the CLI.' },
  { title: 'Health checks', url: 'https://docs.example.com/deployments/health-checks', snippet: 'A deployment is promoted only after every region reports healthy.' },
];

export const assistantTool: AssistantTool = {
  name: 'list_deployments',
  args: { project: 'web-app', since: '7d' },
  result: { count: 14, succeeded: 13, rolledBack: 1, latest: 'v3.2.0' },
  durationMs: 600,
};

export const assistantReply = `This week **web-app** shipped 14 deployments:

| Status | Count |
| --- | --- |
| Succeeded | 13 |
| Rolled back | 1 |

The rollback was \`v3.1.4\`: its health check failed in one region, so traffic stayed on the previous build.

To pin the current release from the CLI:

\`\`\`bash
deploy pin --project web-app --version v3.2.0
\`\`\`

The [rollback guide](https://docs.example.com/deployments/rollback) has the full steps.`;

export const assistantBreadcrumbs: BreadcrumbItem[] = [{ label: 'Acme Industries', href: '/overview' }, { label: 'Assistant' }];

/** Splits text into small chunks to imitate token streaming. */
export function chunkReply(text: string, size = 6): string[] {
  const out: string[] = [];
  for (let i = 0; i < text.length; i += size) out.push(text.slice(i, i + size));
  return out;
}

import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import { SidebarLayout, type BreadcrumbItem, type NavGroup, type SidebarLayoutProps, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}
